// GetDiagnosis (RIVTA) -> Provenance. THE SHARED/PORTABLE FML FILE companion to
// get-diagnosis-to-condition.map (see that file's header comment for the full account of the
// source-model switch) - mirrors ProvenanceBuilder.build() in
// se.inera.ehds.mapping.tk.ProvenanceBuilder (mapping-engine). Confirmed to compile and run
// unchanged on both MaLaC-HD 1.10.0 and HAPI's StructureMapUtilities.
//
// Source: EHDS-TK's published inera-ehds-lm-diagnosis logical model - same as
// get-diagnosis-to-condition.map; shares one source document per record (one tjanstekontrakt,
// two target resources, two StructureMap files - transform() only ever has one target, see
// below).
//
// Unlike the Condition map, this one needs NO ConceptMap/translate() and NO "&" at all: the
// two derived agents are keyed by plain Identifier.value strings with a single FIXED HSA
// namingsystem URI literal ('urn:oid:1.2.752.129.2.1.4.1', see naming-systems.yaml), not a
// per-record OID lookup.
//
// NOTE (portable across engines, verified by compiling/running both ways): a nested backbone
// element with no FHIR StructureDefinition of its own (Provenance.agent, BackboneElement) is
// built WITHOUT create() here - "tgt.agent as custAgent then {...}", letting each engine's own
// reflection pick the right concrete type (malac.models.fhir.rX.Provenance_Agent on MaLaC-HD,
// confirmed by inspecting the generated code; Base.makeProperty() on HAPI, per
// fml-evaluation.md fynd 4, "en transform() tar bara EN target" sidebar on nested backbone
// elements). create('Provenance_Agent') ALSO compiles on MaLaC-HD (the earlier, model-specific
// version of this file used it successfully) but is REJECTED by HAPI ("Unknown Resource or
// Type Name" - nested BackboneElements have no standalone StructureDefinition there) - so the
// no-create() form is the one that is actually portable, not the MaLaC-HD-only form this file
// used before the model switch. See malac-hd-evaluation.md, "Den portabla delmangden av FML".
//
// Provenance.target and Provenance.recorded are intentionally left for the driver
// (run_pipeline.py) to fill in after both this map and get-diagnosis-to-condition.map have run
// against the same record: target needs the Condition's own generated id (two separate
// compiled transforms produce the two resources - a transform() takes one source and one
// target, see fml-evaluation.md's "en transform() tar bara EN target", confirmed true for
// MaLaC-HD too), and recorded needs authorTime converted to a TRUE UTC instant rather than the
// local-offset dateTime get-diagnosis-to-condition.map's recordedDate uses for the SAME raw
// field - two different conversions of one source value, done once each by
// lm_diagnosis_json_builder.py (see riv_date.py).
//
// assembler's HSA-id (the bridge's own identity) is not part of the RIVTA source at all - a
// per-deployment configuration constant, built here as a LITERAL (no "&", no model navigation,
// so no engine-specific risk either way) rather than added by calling code afterwards, so one
// compiled call produces the complete three-agent Provenance. Matches
// GetDiagnosisMapperTest's MapperContext bridgeHsaId literal ("SE2321000999-EHDS") so the two
// outputs are directly comparable.
map "http://ehds-brygga.inera.se/fhir/StructureMap/GetDiagnosisToProvenance" = "GetDiagnosisToProvenance"

uses "https://fhir.inera.se/ig/ehds-tk/StructureDefinition/inera-ehds-lm-diagnosis" alias LmDiagnosis as source
uses "http://hl7.org/fhir/StructureDefinition/Provenance" alias Provenance as target

group GetDiagnosisToProvenance(source src : LmDiagnosis, target tgt : Provenance) {
  src.diagnosis as d then {
    d.diagnosisHeader as h then {
      h.accountableHealthcareProfessional as ahp then {
        // custodian: careGiverHSAId.
        ahp.healthcareProfessionalCareGiverHSAId as giver then {
          giver.value as giverVal -> tgt.agent as custAgent then {
            giverVal -> custAgent.type = cc('http://terminology.hl7.org/CodeSystem/provenance-participant-type', 'custodian') "custodian-type";
            giverVal -> custAgent.who = create('Reference') as custWho then {
              giverVal -> custWho.identifier = create('Identifier') as custId then {
                giverVal as giverValSys -> custId.system = 'urn:oid:1.2.752.129.2.1.4.1' "custodian-identifier-system";
                giverVal as giverValV -> custId.value = giverValV "custodian-identifier-value";
              } "custodian-identifier";
            } "custodian-who";
          } "custodian-agent";
        } "giver";

        // author: careUnitHSAId.
        ahp.healthcareProfessionalCareUnitHSAId as unit then {
          unit.value as unitVal -> tgt.agent as authAgent then {
            unitVal -> authAgent.type = cc('http://terminology.hl7.org/CodeSystem/provenance-participant-type', 'author') "author-type";
            unitVal -> authAgent.who = create('Reference') as authWho then {
              unitVal -> authWho.identifier = create('Identifier') as authId then {
                unitVal as unitValSys -> authId.system = 'urn:oid:1.2.752.129.2.1.4.1' "author-identifier-system";
                unitVal as unitValV -> authId.value = unitValV "author-identifier-value";
              } "author-identifier";
            } "author-who";
          } "author-agent";
        } "unit";
      } "ahp";
    } "header";
  } "diagnosis";

  // assembler: see the file header comment.
  src -> tgt.agent as asmAgent then {
    src -> asmAgent.type = cc('http://terminology.hl7.org/CodeSystem/provenance-participant-type', 'assembler') "assembler-type";
    src -> asmAgent.who = create('Reference') as asmWho then {
      src -> asmWho.identifier = create('Identifier') as asmId then {
        src -> asmId.system = 'urn:oid:1.2.752.129.2.1.4.1' "assembler-identifier-system";
        src -> asmId.value = 'SE2321000999-EHDS' "assembler-identifier-value";
      } "assembler-identifier";
    } "assembler-who";
  } "assembler-agent";
}
